import{_ as e,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"模型查询 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"检索多个模型","slug":"检索多个模型","link":"#检索多个模型","children":[{"level":3,"title":"访问列值","slug":"访问列值","link":"#访问列值","children":[]},{"level":3,"title":"添加附加约束","slug":"添加附加约束","link":"#添加附加约束","children":[]},{"level":3,"title":"集合","slug":"集合","link":"#集合","children":[]},{"level":3,"title":"分块结果","slug":"分块结果","link":"#分块结果","children":[]}]},{"level":2,"title":"检索单个模型","slug":"检索单个模型","link":"#检索单个模型","children":[{"level":3,"title":"未找到异常","slug":"未找到异常","link":"#未找到异常","children":[]},{"level":3,"title":"检索聚合","slug":"检索聚合","link":"#检索聚合","children":[]}]},{"level":2,"title":"插入和更新模型","slug":"插入和更新模型","link":"#插入和更新模型","children":[{"level":3,"title":"基本插入","slug":"基本插入","link":"#基本插入","children":[]},{"level":3,"title":"基本更新","slug":"基本更新","link":"#基本更新","children":[]},{"level":3,"title":"批量赋值","slug":"批量赋值","link":"#批量赋值","children":[]},{"level":3,"title":"其他创建方法","slug":"其他创建方法","link":"#其他创建方法","children":[]}]},{"level":2,"title":"删除模型","slug":"删除模型","link":"#删除模型","children":[]},{"level":2,"title":"查询作用域","slug":"查询作用域","link":"#查询作用域","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/database/model.md","filePath":"3.x/zh-cn/extend/database/model.md"}'),u={name:"3.x/zh-cn/extend/database/model.md"};function r(k,s,d,g,h,f){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"模型查询",-1)),a(p),s[1]||(s[1]=i(`<p>从数据库请求数据时，模型将主要使用 <code>get</code> 或 <code>first</code> 方法检索值，取决于您希望检索多个模型还是检索单个模型。从 Model 派生的查询返回 <code>October\\Rain\\Database\\Builder</code> 的实例。</p><h2 id="检索多个模型"><a href="#检索多个模型" class="header-anchor">#</a> 检索多个模型</h2><p>创建模型及<a href="./structure.html">其关联的数据库表</a>后，您就可以开始从数据库中检索数据了。将每个模型视为一个强大的<a href="./query.html">查询构建器</a>，允许您查询与模型关联的数据库表。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flights</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="访问列值"><a href="#访问列值" class="header-anchor">#</a> 访问列值</h3><p>如果您有一个模型实例，您可以通过访问相应的属性来访问模型的列值。例如，让我们遍历查询返回的每个 <code>Flight</code> 实例并输出 <code>name</code> 列的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="添加附加约束"><a href="#添加附加约束" class="header-anchor">#</a> 添加附加约束</h3><p><code>all</code> 方法将返回模型表中的所有结果。由于每个模型都充当<a href="./query.html">查询构建器</a>，您还可以向查询添加约束，然后使用 <code>get</code> 方法检索结果：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flights</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">take</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>由于模型是查询构建器，您应该熟悉<a href="./query.html">查询构建器</a>上所有可用的方法。您可以在模型查询中使用这些方法中的任何一个。</p></div><h3 id="集合"><a href="#集合" class="header-anchor">#</a> 集合</h3><p>对于 <code>all</code> 和 <code>get</code> 等检索多个结果的方法，将返回一个 <code>Collection</code> 实例。这个类提供了<a href="./collection.html">多种有用的方法</a>来处理您的结果。当然，您可以像数组一样简单地遍历此集合。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="分块结果"><a href="#分块结果" class="header-anchor">#</a> 分块结果</h3><p>如果您需要处理数千条记录，请使用 <code>chunk</code> 命令。<code>chunk</code> 方法将检索一&quot;块&quot;模型，将它们提供给给定的 <code>Closure</code> 进行处理。使用 <code>chunk</code> 方法可以在处理大型结果集时节省内存。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">chunk</span><span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$flights</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>传递给方法的第一个参数是您希望每个&quot;块&quot;接收的记录数。作为第二个参数传递的 Closure 将为从数据库检索的每个块调用。</p><h2 id="检索单个模型"><a href="#检索单个模型" class="header-anchor">#</a> 检索单个模型</h2><p>除了检索给定表的所有记录外，您还可以使用 <code>find</code> 和 <code>first</code> 检索单个记录。这些方法不是返回模型集合，而是返回单个模型实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 通过主键检索模型</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 检索与查询约束匹配的第一个模型</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="未找到异常"><a href="#未找到异常" class="header-anchor">#</a> 未找到异常</h3><p>有时您可能希望在未找到模型时抛出异常。这在路由或控制器中特别有用。<code>findOrFail</code> 和 <code>firstOrFail</code> 方法将检索查询的第一个结果。但是，如果未找到结果，将抛出 <code>Illuminate\\Database\\Eloquent\\ModelNotFoundException</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">findOrFail</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;legs&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">firstOrFail</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在<a href="./../system/routing.html">开发 API</a> 时，如果未捕获异常，会自动向用户发送 <code>404</code> HTTP 响应，因此使用这些方法时不需要编写显式检查来返回 <code>404</code> 响应。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/api/flights/{id}&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">findOrFail</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="检索聚合"><a href="#检索聚合" class="header-anchor">#</a> 检索聚合</h3><p>您还可以使用查询构建器提供的 <code>count</code>、<code>sum</code>、<code>max</code> 和其他<a href="./query.html">聚合函数</a>。这些方法返回适当的标量值而不是完整的模型实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$count</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$max</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="插入和更新模型"><a href="#插入和更新模型" class="header-anchor">#</a> 插入和更新模型</h2><p>插入和更新数据是模型的核心功能，与传统 SQL 语句相比，它使过程变得轻松。</p><h3 id="基本插入"><a href="#基本插入" class="header-anchor">#</a> 基本插入</h3><p>要在数据库中创建新记录，只需创建一个新的模型实例，在模型上设置属性，然后调用 <code>save</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Sydney to Canberra&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在此示例中，我们只是创建了 <code>Flight</code> 模型的新实例并分配了 <code>name</code> 属性。当我们调用 <code>save</code> 方法时，一条记录将被插入数据库。<code>created_at</code> 和 <code>updated_at</code> 时间戳也将自动设置，因此无需手动设置。</p><h3 id="基本更新"><a href="#基本更新" class="header-anchor">#</a> 基本更新</h3><p><code>save</code> 方法也可以用于更新数据库中已存在的模型。要更新模型，您应该检索它，设置您希望更新的任何属性，然后调用 <code>save</code> 方法。同样，<code>updated_at</code> 时间戳将自动更新，因此无需手动设置其值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Darwin to Adelaide&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>也可以对匹配给定查询的任意数量的模型执行更新。在此示例中，所有 <code>active</code> 且 <code>destination</code> 为 <code>San Diego</code> 的航班将被标记为延误：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;destination&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Perth&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;delayed&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>update</code> 方法期望一个列和值对的数组，表示应该更新的列。</p><h3 id="批量赋值"><a href="#批量赋值" class="header-anchor">#</a> 批量赋值</h3><p>您也可以使用 <code>create</code> 方法在一行中保存新模型。插入的模型实例将从方法返回给您。但是，在此之前，您需要在模型上指定 <code>fillable</code> 或 <code>guarded</code> 属性，因为所有模型都会防止批量赋值。请注意，<code>fillable</code> 和 <code>guarded</code> 都不影响后端表单的提交，只影响 <code>create</code> 或 <code>fill</code> 方法的使用。</p><p>当用户通过请求传递意外的 HTTP 参数，并且该参数更改了您意料之外的数据库列时，就会发生批量赋值漏洞。例如，恶意用户可能通过 HTTP 请求发送 <code>is_admin</code> 参数，然后将其映射到模型的 <code>create</code> 方法，允许用户将自己提升为管理员。</p><p>要开始，您应该定义哪些模型属性可以批量赋值。您可以使用模型上的 <code>$fillable</code> 属性来实现。例如，让我们使 <code>Flight</code> 模型的 <code>name</code> 属性可以批量赋值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Flight</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array fillable attributes that are mass assignable.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$fillable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦我们使属性可以批量赋值，我们就可以使用 <code>create</code> 方法在数据库中插入新记录。<code>create</code> 方法返回已保存的模型实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>虽然 <code>$fillable</code> 充当应该可以批量赋值的属性的&quot;允许列表&quot;，您也可以选择使用 <code>$guarded</code>。<code>$guarded</code> 属性应该包含您不希望被批量赋值的属性数组。不在数组中的所有其他属性将是可批量赋值的。因此，<code>$guarded</code> 的功能类似于&quot;阻止列表&quot;。当然，您应该使用 <code>$fillable</code> 或 <code>$guarded</code> - 而不是两者同时使用：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Flight</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * The attributes that aren&#39;t mass assignable.
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在上面的示例中，除了 <code>price</code> 之外的所有属性都将是可批量赋值的。</p><h3 id="其他创建方法"><a href="#其他创建方法" class="header-anchor">#</a> 其他创建方法</h3><p>有时您可能只想实例化一个模型的新实例。您可以使用 <code>make</code> 方法来实现。<code>make</code> 方法将简单地返回一个新实例，而不保存或创建任何内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 功能上等同于...</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>还有另外两个方法可以通过批量赋值属性来创建模型：<code>firstOrCreate</code> 和 <code>firstOrNew</code>。<code>firstOrCreate</code> 方法将尝试使用给定的列/值对定位数据库记录。如果在数据库中找不到模型，将使用给定的属性插入一条记录。</p><p><code>firstOrNew</code> 方法与 <code>firstOrCreate</code> 一样，将尝试在数据库中定位与给定属性匹配的记录。但是，如果未找到模型，将返回一个新的模型实例。请注意，<code>firstOrNew</code> 返回的模型尚未持久化到数据库。您需要手动调用 <code>save</code> 来持久化它：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 通过属性检索航班，否则创建它</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">firstOrCreate</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 通过属性检索航班，或实例化一个新实例</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">firstOrNew</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="删除模型"><a href="#删除模型" class="header-anchor">#</a> 删除模型</h2><p>要删除模型，请在模型实例上调用 <code>delete</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在上面的示例中，我们在调用 <code>delete</code> 方法之前从数据库检索模型。但是，如果您知道模型的主键，您可以在不检索模型的情况下删除它。为此，请调用 <code>destroy</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以对一组模型运行删除查询。在此示例中，我们将删除所有标记为不活跃的航班：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deletedRows</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>需要注意的是，直接从查询中删除记录时，<a href="./../system/models.html">模型事件</a>不会触发。</p></div><h2 id="查询作用域"><a href="#查询作用域" class="header-anchor">#</a> 查询作用域</h2><p>作用域允许您定义可以在整个应用程序中轻松重用的常见约束集。例如，您可能需要频繁检索所有被认为是&quot;热门&quot;的用户。要定义作用域，只需在模型方法前加上 <code>scope</code> 前缀。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * scopePopular query to only include popular users.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopePopular</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * scopeActive query to only include active users.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeActive</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦定义了作用域，您可以在查询模型时调用作用域方法。但是，调用方法时不需要包含 <code>scope</code> 前缀。您甚至可以链接调用各种作用域，例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">popular</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">active</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>有时您可能希望定义一个接受参数的作用域。首先，只需将额外的参数添加到您的作用域。作用域参数应该定义在 <code>$query</code> 参数之后：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * Scope a query to only include users of a given type.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyType</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>现在您可以在调用作用域时传递参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">applyType</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../system/models.html">模型文章</a></li></ul></div>`,76))])}const b=e(u,[["render",r]]);export{v as __pageData,b as default};
